using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count * 2)
        {
            var vecs = MemoryMarshal.Cast<float, Vector<float>>(values);

            // Use two accumulators to exploit instruction-level parallelism
            var acc0 = Vector<float>.One;
            var acc1 = Vector<float>.One;

            int vLen = vecs.Length;
            int vEnd = vLen - (vLen & 1); // round down to even

            for (int v = 0; v < vEnd; v += 2)
            {
                acc0 *= vecs[v];
                acc1 *= vecs[v + 1];
            }

            if ((vLen & 1) != 0)
                acc0 *= vecs[vLen - 1];

            acc0 *= acc1;

            // Horizontal reduction
            float product = 1f;
            for (int lane = 0; lane < Vector<float>.Count; lane++)
                product *= acc0[lane];

            // Handle remaining scalar elements
            i = vecs.Length * Vector<float>.Count;
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4-way unroll to reduce loop overhead
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int end = values.Length - 3;
        for (; i < end; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        for (; i < values.Length; i++)
            p0 *= values[i];

        return p0 * p1 * p2 * p3;
    }
}

